class Solution(object):
    def myAtoi(self, s):
        INT_MAX = 2147483647
        INT_MIN = -2147483648
        i = 0
        n = len(s)
        while i < n and s[i] == ' ':
            i += 1
        if i >= n:
            return 0
        sign = 1
        if s[i] == '+':
            sign = 1
            i += 1
        elif s[i] == '-':
            sign = -1
            i += 1
        result = 0
        while i < n and '0' <= s[i] <= '9':
            digit = ord(s[i]) - ord('0')
            if sign == 1:
