typedef struct { char* s; int pos; int len; } Tok;
static void skipWS(Tok* t) {
    while (t->pos < t->len && (t->s[t->pos] == ' ' || t->s[t->pos] == ',' || t->s[t->pos] == '\t' || t->s[t->pos] == '\n' || t->s[t->pos] == '\r')) t->pos++;
}
static char* nextToken(Tok* t) {
    skipWS(t);
    if (t->pos >= t->len) return NULL;
    int start = t->pos;
    if (t->s[t->pos] == '[') {
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') { depth--; if (depth == 0) break; }
        }
        int token_len = t->pos - start;
        char* token = (char*)malloc(token_len + 1);
        strncpy(token, t->s + start, token_len);
        token[token_len] = '\0';
        return token;
    } else if (t->s[t->pos] == '"') {
        t->pos++;
        int bi = 0;
        char* buf = (char*)malloc(t->len - t->pos + 1);
        while (t->pos < t->len && t->s[t->pos] != '"') {
            buf[bi++] = t->s[t->pos++];
        }
        buf[bi] = '\0';
        if (t->pos < t->len && t->s[t->pos] == '"') t->pos++;
        return buf;
    } else {
        while (t->pos < t->len && t->s[t->pos] != ',' && t->s[t->pos] != ']' && t->s[t->pos] != '[') t->pos++;
