int myAtoi(const char* str) {
    if (!str) return 0;
    const int INT_MAX_V = INT_MAX;
    const int INT_MIN_V = INT_MIN;
    int i = 0;
    int n = (int)strlen(str);
    // skip leading whitespace
    while (i < n && str[i] == ' ') i++;
    if (i >= n) return 0;
    int sign = 1;
    if (str[i] == '+') { sign = 1; i++; }
    else if (str[i] == '-') { sign = -1; i++; }
    int result = 0; // use 32-bit accumulation; pre-checks prevent overflow
    while (i < n && str[i] >= '0' && str[i] <= '9') {
        int digit = str[i] - '0';
        if (sign == 1) {
            if (result > (INT_MAX_V - digit) / 10) return INT_MAX_V;
        } else {
            // For negative, compare against INT_MAX+1 range using unsigned arithmetic to avoid 64-bit
            unsigned int limit = (unsigned int)INT_MAX_V + 1u;
            if ((unsigned int)result > (limit - (unsigned int)digit) / 10u) return INT_MIN_V;
        }
        result = result * 10 + digit;
        i++;
    }
    int final = result * sign;
    if (final > INT_MAX_V) return INT_MAX_V;
    if (final < INT_MIN_V) return INT_MIN_V;
    return final;
}

